sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var config = _getConfig(current.use_case.toString());
    if (!config) {
        gs.warn('No priority config found for use_case: ' + current.use_case);
        return;
    }

    var levelMap = { 'Critical': 1, 'High': 2, 'Medium': 3, 'Low': 4 };
    var level = levelMap[config.basePriority] || 3;

    current.current_priority = level.toString();
    current.priority_reason = 'Priority set to "' + config.basePriority +
                               '" based on the base priority configured for use case "' +
                               current.use_case + '".';
    // No current.update() — After rule auto-saves field changes

    function _getConfig(useCase) {
        var gr = new GlideRecord('x_snc_campus_foo_1_use_case_priority');
        gr.addQuery('use_case', useCase);
        gr.addQuery('active', true);
        gr.query();
        if (gr.next()) {
            return {
                basePriority: gr.base_priority.toString(),
                safetyCritical: gr.safety_critical == true
            };
        }
        return null;
    }

})(current, previous);

